"use client";

import { useEffect, useRef, useState } from "react";
import {
  buildGazeMessage,
  findLookTarget,
  startExpressionDetection,
} from "../utils/utils";
import styles from "./FaceExpressions.module.css";

const IDLE_GAZE_MESSAGE =
  "Click Detect face. Look at the center dot for a moment, then look around the screen.";

function readLookRegions(root) {
  return [...root.querySelectorAll("[data-look]")].map((element) => {
    const rect = element.getBoundingClientRect();
    return {
      name: element.dataset.look,
      left: rect.left,
      top: rect.top,
      right: rect.right,
      bottom: rect.bottom,
    };
  });
}

function classNames(...names) {
  return names.filter(Boolean).join(" ");
}

export default function FaceExpression() {
  const pageRef = useRef(null);
  const videoRef = useRef(null);
  const sessionRef = useRef(null);

  const [expression, setExpression] = useState("Detection is off");
  const [error, setError] = useState("");
  const [isRunning, setIsRunning] = useState(false);
  const [isStarting, setIsStarting] = useState(false);
  const [gaze, setGaze] = useState(null);
  const [activeLook, setActiveLook] = useState("");
  const [lookMessage, setLookMessage] = useState(IDLE_GAZE_MESSAGE);

  useEffect(() => () => sessionRef.current?.stop(), []);

  function updateGazeMessage(nextGaze) {
    if (!nextGaze) {
      setActiveLook("");
      setLookMessage("No face detected, so I can't see where your eyes are looking.");
      return;
    }

    if (nextGaze.calibrating) {
      setActiveLook("");
      setLookMessage("Look at the center of the screen while your eyes are measured.");
      return;
    }

    const regions = pageRef.current ? readLookRegions(pageRef.current) : [];
    const target = findLookTarget(nextGaze.x, nextGaze.y, regions, {
      width: window.innerWidth,
      height: window.innerHeight,
    });

    setActiveLook(target?.name ?? "");
    setLookMessage(
      buildGazeMessage({
        targetName: target?.name,
        x: nextGaze.x,
        y: nextGaze.y,
      })
    );
  }

  function start() {
    const video = videoRef.current;
    if (!video || sessionRef.current) return;

    setError("");
    setIsStarting(true);
    setExpression("Starting camera...");
    setLookMessage("Starting camera...");

    sessionRef.current = startExpressionDetection({
      video,
      onRunning: () => {
        setIsStarting(false);
        setIsRunning(true);
      },
      onUpdate: ({ expression: nextExpression, gaze: nextGaze }) => {
        setExpression(nextExpression);
        setGaze(nextGaze);
        updateGazeMessage(nextGaze);
      },
      onError: (message) => {
        sessionRef.current?.stop();
        sessionRef.current = null;
        setIsStarting(false);
        setIsRunning(false);
        setGaze(null);
        setActiveLook("");
        setExpression("Detection is off");
        setLookMessage(IDLE_GAZE_MESSAGE);
        setError(message);
      },
    });
  }

  function stop() {
    sessionRef.current?.stop();
    sessionRef.current = null;
    setIsStarting(false);
    setIsRunning(false);
    setGaze(null);
    setActiveLook("");
    setExpression("Detection is off");
    setLookMessage(IDLE_GAZE_MESSAGE);
  }

  function recenter() {
    sessionRef.current?.recenter();
    setLookMessage("Look at the center of the screen while your eyes are measured.");
  }

  function activeClass(name) {
    return activeLook === name ? styles.active : "";
  }

  return (
    <main ref={pageRef} className={styles.page}>
      <header className={styles.header}>
        <div data-look="the title" className={activeClass("the title")}>
          <h1 className={styles.title}>AI Face Expression Detection</h1>
          <p className={styles.subtitle}>
            Start the camera, then look around. The blue dot and the text follow your eyes.
          </p>
        </div>

        <button
          type="button"
          data-look="the detect button"
          onClick={isRunning ? stop : start}
          disabled={isStarting}
          className={classNames(
            styles.button,
            isRunning && styles.stop,
            activeClass("the detect button")
          )}
        >
          {isStarting ? "Starting camera..." : isRunning ? "Stop detection" : "Detect face"}
        </button>
      </header>

      <section className={styles.stage}>
        <div
          data-look="the camera preview"
          className={classNames(styles.videoWrap, activeClass("the camera preview"))}
        >
          <video ref={videoRef} autoPlay muted playsInline className={styles.video} />
          {!isRunning && (
            <div className={styles.offline}>Camera is off. Click Detect face to begin.</div>
          )}
        </div>

        <div className={styles.side}>
          <article
            data-look="the expression result"
            className={classNames(styles.card, activeClass("the expression result"))}
          >
            <p className={styles.label}>Detected expression</p>
            <p className={styles.expression}>{expression}</p>
            {isRunning && <p className={styles.status}>Camera is running</p>}
            {error && <p className={styles.error}>{error}</p>}
          </article>

          <article
            data-look="the eye direction message"
            className={classNames(
              styles.card,
              styles.gazeCard,
              activeClass("the eye direction message")
            )}
          >
            <p className={styles.label}>Where you are looking</p>
            <p className={styles.gazeText} aria-live="polite">
              {lookMessage}
            </p>
            {isRunning && !gaze?.calibrating && (
              <button
                type="button"
                data-look="the recenter button"
                onClick={recenter}
                className={classNames(styles.ghostButton, activeClass("the recenter button"))}
              >
                Recenter eyes
              </button>
            )}
          </article>
        </div>
      </section>

      {isRunning && gaze?.calibrating && (
        <div className={styles.centerCue}>
          <div className={styles.centerDot} />
          <p className={styles.centerLabel}>Look here</p>
        </div>
      )}

      {isRunning && gaze && !gaze.calibrating && (
        <div
          aria-hidden
          className={styles.gazeDot}
          style={{ left: `${gaze.x * 100}%`, top: `${gaze.y * 100}%` }}
        />
      )}
    </main>
  );
}
